#!/usr/bin/env bash

# Non-secret settings shared by the deployment scripts and actions.
DEPLOY_BASE_URL="https://lorenzochukwuebuka.com.ng"
DEPLOY_REMOTE_ROOT_NAME="production"
DEPLOY_RELEASES_DIRECTORY="releases"
DEPLOY_SHARED_DIRECTORY="shared"
DEPLOY_CURRENT_LINK="current"
DEPLOY_RELEASE_RETENTION=5
DEPLOY_SSH_ALIAS="litehost-production"
DEPLOY_SSH_CONNECT_TIMEOUT=10
DEPLOY_SSH_DEFAULT_PORT=22
DEPLOY_REMOTE_HOME_PATTERN='^/var/www/[A-Za-z0-9._-]+$'
DEPLOY_SMOKE_RETRIES=8
DEPLOY_SMOKE_RETRY_DELAY=10

# Litehost currently uses SSH port 22. The repository variable may override it.
DEPLOY_SSH_PORT="${DEPLOY_SSH_PORT:-$DEPLOY_SSH_DEFAULT_PORT}"

export DEPLOY_BASE_URL DEPLOY_REMOTE_ROOT_NAME DEPLOY_RELEASES_DIRECTORY
export DEPLOY_SHARED_DIRECTORY DEPLOY_CURRENT_LINK DEPLOY_RELEASE_RETENTION
export DEPLOY_SSH_ALIAS DEPLOY_SSH_CONNECT_TIMEOUT DEPLOY_SSH_DEFAULT_PORT DEPLOY_REMOTE_HOME_PATTERN DEPLOY_SMOKE_RETRIES
export DEPLOY_SMOKE_RETRY_DELAY DEPLOY_SSH_PORT
